//! Generated by `rust-anything app wire` from rust-anything.json; it is rewritten on every wire.

use std::ffi::OsString;
use std::process::ExitCode;

use clap::ArgMatches;

mod gemini_webapi;
mod ask;
mod models;
mod list;
mod read;
mod reply;
mod download;
mod inspect;
mod research_send;
mod research_check;
mod research_get;

// `RUST_ANYTHING_UNIT_<NAME>=original` sends that unit back to the original.
fn sent_to_original(unit: &str) -> bool {
    std::env::var(format!("RUST_ANYTHING_UNIT_{unit}")).is_ok_and(|v| v == "original")
}

pub fn dispatch(command: &str, matches: &ArgMatches) -> Option<ExitCode> {
    let args: Vec<String> = matches
        .get_many::<OsString>("args")
        .into_iter()
        .flatten()
        .map(|a| a.to_string_lossy().into_owned())
        .collect();

    // Find the subcommand: skip global flags that come before it
    let subcommand = args.iter().find(|a| {
        matches!(a.as_str(), "ask" | "reply" | "research" | "list" | "read" | "models" | "download" | "inspect")
    });

    match subcommand.map(|s| s.as_str()) {
        Some("ask") if !sent_to_original("ASK") => Some(ask::run(command, matches)),
        Some("models") if !sent_to_original("MODELS") => Some(models::run(command, matches)),
        Some("list") if !sent_to_original("LIST") => Some(list::run(command, matches)),
        Some("read") if !sent_to_original("READ") => Some(read::run(command, matches)),
        Some("reply") if !sent_to_original("REPLY") => Some(reply::run(command, matches)),
        Some("download") if !sent_to_original("DOWNLOAD") => Some(download::run(command, matches)),
        Some("inspect") if !sent_to_original("INSPECT") => Some(inspect::run(command, matches)),
        Some("research") => {
            // research has sub-subcommands: send, check, get
            let res_sub = args.iter().find(|a| matches!(a.as_str(), "send" | "check" | "get"));
            match res_sub.map(|s| s.as_str()) {
                Some("send") if !sent_to_original("RESEARCH_SEND") => {
                    Some(research_send::run(command, matches))
                }
                Some("check") if !sent_to_original("RESEARCH_CHECK") => {
                    Some(research_check::run(command, matches))
                }
                Some("get") if !sent_to_original("RESEARCH_GET") => {
                    Some(research_get::run(command, matches))
                }
                _ => None,
            }
        }
        _ if command == "cli" && !sent_to_original("GEMINI_WEBAPI") => {
            Some(gemini_webapi::run(command, matches))
        }
        _ => None,
    }
}
